<?php
declare(strict_types=1);

use MiniERP\Application\Services\InventoryAdjustmentService;
use MiniERP\Application\Services\InventoryCountInput;
use MiniERP\Infrastructure\Audit\AuditLogger;
use MiniERP\Infrastructure\Database\AuditSchema;
use MiniERP\Infrastructure\Database\InventorySchema;
use MiniERP\Infrastructure\Database\MasterSchema;
use MiniERP\Infrastructure\Database\PurchaseSchema;
use MiniERP\Infrastructure\Database\SalesSchema;
use MiniERP\Infrastructure\Database\TransactionManager;
use MiniERP\Security\Actor;
use MiniERP\Security\RolesInstaller;

if(PHP_SAPI!=='cli'||!is_file('/var/www/html/wp-load.php')){fwrite(STDERR,"Local WordPress CLI is required.\n");exit(2);}require_once '/var/www/html/wp-load.php';require_once WP_PLUGIN_DIR.'/mini-erp/mini-erp.php';global $wpdb;
$assert=static function(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);};$assert(wp_get_environment_type()==='local'&&DB_NAME==='mini_erp_local'&&$wpdb->prefix==='paxg_','Refusing to run outside the local fixture database.');
$prefix='paxg_test_inventory_'.bin2hex(random_bytes(5)).'_';$assert((bool)preg_match('/\Apaxg_test_inventory_[a-f0-9]{10}_\z/D',$prefix),'Generated inventory fixture prefix is unsafe.');$db=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$db->prefix=$prefix;
$tables=array_map(static fn(string $suffix):string=>$prefix.'erp_'.$suffix,['stock_adjustment_items','stock_adjustments','stock_movements','stock_balances','shipment_items','shipments','sales_order_items','sales_orders','goods_receipt_items','goods_receipts','purchase_order_items','purchase_orders','products','categories','warehouses','customers','suppliers','audit_logs']);$passed=[];$failure=null;$exit=0;
try{
    (new MasterSchema($db))->migrate();(new AuditSchema($db))->migrate();(new SalesSchema($db))->migrate();(new PurchaseSchema($db))->migrate();(new InventorySchema($db))->migrate();
    foreach($tables as $table)$assert((int)$db->get_var($db->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s',DB_NAME,$table))===1,'A required inventory fixture table was not created.');$passed[]='isolated master, stock-ledger, and adjustment schemas created';
    $db->insert($prefix.'erp_categories',['code'=>'INV-TEST','name'=>'Inventory test']);$category=(int)$db->insert_id;$productIds=[];
    foreach(['INV-A','INV-B','INV-C','INV-D'] as $sku){$db->insert($prefix.'erp_products',['sku'=>$sku,'name'=>$sku,'category_id'=>$category,'unit'=>'ea','unit_step'=>'1.000','sale_price_vnd'=>100]);$productIds[]=(int)$db->insert_id;}
    $db->insert($prefix.'erp_warehouses',['code'=>'INV-WH','name'=>'Inventory warehouse']);$warehouse=(int)$db->insert_id;
    foreach([[0,5],[1,3],[2,2],[3,0]] as [$i,$qty]){$productId=$productIds[$i];$db->insert($prefix.'erp_stock_balances',['warehouse_id'=>$warehouse,'product_id'=>$productId,'quantity'=>(string)$qty]);if($qty>0)$db->insert($prefix.'erp_stock_movements',['warehouse_id'=>$warehouse,'product_id'=>$productId,'movement_key'=>'FIXTURE:'.$productId,'direction'=>'IN','qty'=>(string)$qty,'before_qty'=>'0.000','after_qty'=>(string)$qty,'source_type'=>'GOODS_RECEIPT','source_id'=>100+$productId,'actor_id'=>99,'occurred_at'=>gmdate('Y-m-d H:i:s')]);}
    $whCaps=RolesInstaller::definitions()['erp_warehouse']['capabilities'];$managerCaps=RolesInstaller::definitions()['erp_manager']['capabilities'];$warehouseActor=new Actor(10,'erp_warehouse',$whCaps,[$warehouse]);$applier=new Actor(11,'erp_warehouse',$whCaps,[$warehouse]);$manager=new Actor(20,'erp_manager',$managerCaps);$service=new InventoryAdjustmentService($db,new TransactionManager($db),new AuditLogger($prefix));
    try{$service->startDraft(new Actor(12,'erp_warehouse',$whCaps,[]),$warehouse,'Wrong warehouse');throw new RuntimeException('Unassigned warehouse could start an adjustment.');}catch(DomainException){}$passed[]='warehouse assignment is enforced when starting a count';
    $draft=$service->startDraft($warehouseActor,$warehouse,'Quarterly physical count');$counts=InventoryCountInput::fromForm([$productIds[0]=>'4',$productIds[1]=>'4',$productIds[2]=>'0',$productIds[3]=>'0']);$assert($counts!==null,'PHP-parsed integer product keys were rejected by the inventory form input adapter.');
    $assert($service->saveDraft($warehouseActor,$draft,$counts,true)==='REQUESTED','Count could not be saved and submitted.');
    try{$service->decide(new Actor($warehouseActor->id,'erp_manager',$managerCaps),$draft,'approve');throw new RuntimeException('A requester approved their own adjustment.');}catch(DomainException){}$assert($service->decide($manager,$draft,'approve')==='APPROVED','Different manager could not approve the adjustment.');$passed[]='count snapshots support zero quantities and enforce requester/approver separation';
    $key=wp_generate_uuid4();$applied=$service->apply($applier,$draft,$key);$assert($applied['status']==='APPLIED','Approved adjustment was not applied.');$assert($service->apply($applier,$draft,$key)['status']==='APPLIED','Repeated apply request was not idempotent.');
    foreach(['4.000','4.000','0.000','0.000'] as $i=>$expected){$actual=(string)$db->get_var($db->prepare('SELECT quantity FROM `'.$prefix.'erp_stock_balances` WHERE warehouse_id=%d AND product_id=%d',$warehouse,$productIds[$i]));$assert(bccomp($actual,$expected,3)===0,'Applied balance did not equal physical count.');}
    $movementCount=(int)$db->get_var($db->prepare('SELECT COUNT(*) FROM `'.$prefix.'erp_stock_movements` WHERE source_type=%s AND source_id=%d','STOCK_ADJUSTMENT',$draft));$assert($movementCount===3,'Each nonzero count delta should create exactly one movement.');$passed[]='adjustment applies all changed products atomically with one ledger movement per delta and idempotent retry';
    $staleDraft=$service->startDraft($warehouseActor,$warehouse,'Stale snapshot test');$staleCounts=[];foreach([3,4,0,0] as $i=>$qty)$staleCounts[]=['product_id'=>$productIds[$i],'counted_qty'=>(string)$qty];$service->saveDraft($warehouseActor,$staleDraft,$staleCounts,true);$service->decide($manager,$staleDraft,'approve');$db->update($prefix.'erp_stock_balances',['quantity'=>'5.000'],['warehouse_id'=>$warehouse,'product_id'=>$productIds[0]]);$stale=$service->apply($applier,$staleDraft,wp_generate_uuid4());$assert($stale['status']==='STALE','Changed balance did not stale the adjustment.');$assert((int)$db->get_var($db->prepare('SELECT COUNT(*) FROM `'.$prefix.'erp_stock_movements` WHERE source_type=%s AND source_id=%d','STOCK_ADJUSTMENT',$staleDraft))===0,'Stale apply emitted a stock movement.');$passed[]='stale snapshot commits STALE status without changing stock ledger';
    $openingDraft=$service->startDraft($warehouseActor,$warehouse,'Opening stock must use a receipt');$openingCounts=[];foreach([5,4,0,1] as $i=>$qty)$openingCounts[]=['product_id'=>$productIds[$i],'counted_qty'=>(string)$qty];$service->saveDraft($warehouseActor,$openingDraft,$openingCounts,true);$service->decide($manager,$openingDraft,'approve');try{$service->apply($applier,$openingDraft,wp_generate_uuid4());throw new RuntimeException('Positive count on a product with no ledger history created opening stock.');}catch(DomainException){}$assert((string)$db->get_var($db->prepare('SELECT status FROM `'.$prefix.'erp_stock_adjustments` WHERE id=%d',$openingDraft))==='APPROVED','Rejected opening-count attempt changed adjustment state.');$assert((string)$db->get_var($db->prepare('SELECT quantity FROM `'.$prefix.'erp_stock_balances` WHERE warehouse_id=%d AND product_id=%d',$warehouse,$productIds[3]))==='0.000','Opening-count rejection changed balance.');$passed[]='opening stock cannot be introduced through a positive physical count without ledger history';
    (new InventorySchema($db))->migrate();$assert((int)$db->get_var($db->prepare('SELECT COUNT(*) FROM `'.$prefix.'erp_stock_adjustments`'))===3,'Repeat migration changed adjustment records.');$passed[]='repeat schema migration preserves adjustment history';
}catch(Throwable $e){$exit=1;$failure='Inventory adjustment smoke failed: '.get_class($e).' ('.$e->getCode().') '.$e->getMessage();}
finally{foreach($tables as $table){if(!preg_match('/\A'.preg_quote($prefix,'/').'erp_[a-z_]+\z/D',$table)){$exit=1;continue;}if($db->query('DROP TABLE IF EXISTS `'.$table.'`')===false){$exit=1;continue;}$remaining=$db->get_var($db->prepare('SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s',DB_NAME,$table));if((string)$remaining!=='0'){$exit=1;$failure='Inventory fixture cleanup could not be verified.';}}$db->close();}
if($failure!==null)fwrite(STDERR,$failure."\n");foreach($passed as $result)fwrite(STDOUT,"PASS: {$result}\n");if($exit!==0)exit($exit);fwrite(STDOUT,"Inventory adjustment smoke passed; exact fixture tables cleaned.\n");
